'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'M3 10 12 3l9 7v11h-6v-7H9v7H3Z',folder:'M3 6h7l2 3h9v12H3ZM3 6V4h7l2 2',work:'M5 3h10l4 4v14H5ZM14 3v5h5M8 12h8M8 16h6',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z',chat:'M3 4h18v13H9l-6 4ZM7 9h10M7 13h6',chart:'M3 21V11h4v10ZM10 21V6h4v15ZM17 21V2h4v19Z',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8ZM12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',arrow:'M4 12h16m-6-6 6 6-6 6',back:'M20 12H4m6-6-6 6 6 6',plus:'M12 4v16M4 12h16',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',menu:'M4 6h16M4 12h16M4 18h16',clock:'M12 8v5l3 2M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',alert:'m12 3 10 18H2ZM12 9v5M12 17v1',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14Zm5 12 6 6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6Zm-4 9 3 3 5-6',file:'M5 3h9l5 5v13H5ZM14 3v6h5',send:'m3 3 18 9-18 9 4-9Zm4 9h14'};
const icon=n=>`<svg class="icon" aria-hidden="true" viewBox="0 0 24 24"><path d="${icons[n]||icons.spark}"/></svg>`;
const link=(text,path,cls='button')=>`<a class="${cls}" href="#/${path}">${text}</a>`;
const button=(text,action,cls='button',attrs='')=>`<button class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
const status=(text,tone='')=>`<span class="status ${tone}">${text}</span>`;
const help=t=>`<button class="help" data-help="${esc(t)}" aria-label="${esc(t)}">?</button>`;
const heading=(k,title,desc='',action='')=>`<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1>${desc?`<p class="description">${desc}</p>`:''}</div>${action}</div>`;
const back=(text,path)=>link(`${icon('back')}${text}`,path,'back');
const empty=(title,desc,action='')=>`<div class="empty">${icon('check')}<h2>${title}</h2><p>${desc}</p>${action}</div>`;
const state={project:'ai-workforce',projects:[{id:'ai-workforce',name:'AI Workforce',description:'Eine ruhige Kommandozentrale für die Zusammenarbeit mit KI.',folder:'/projekte/ai-workforce'},{id:'haushaltsbuch2',name:'Haushaltsbuch',description:'Einnahmen und Ausgaben einfach im Blick behalten.',folder:'/projekte/haushaltsbuch2'}],accepted:false,decision:null,iteration:0,runActive:false,runStopped:false,questionAnswered:false,acknowledged:false,repair:false,filter:'Alle',workTab:'auftraege',capTab:'werkzeuge',projectTab:'ueberblick',usage:'30',mode:'jarvis',messages:[],scenario:'normal',motion:true,tasks:[],createdProject:null,taskDraft:null,chatDraft:null,search:''};
const productContexts={};
let onProductActivated=()=>{},ensureProductTaskItem=()=>{};
function activateProduct(id){if(id===state.project)return;productContexts[state.project]={taskDraft:state.taskDraft,messages:state.messages,chatDraft:state.chatDraft,composerDraft:state.composerDraft||''};state.project=id;const c=productContexts[id]||{};state.taskDraft=c.taskDraft||null;state.messages=c.messages||[];state.chatDraft=c.chatDraft||null;state.composerDraft=c.composerDraft||'';state.search='';state.filter='Alle';onProductActivated();}
const project=()=>state.projects.find(p=>p.id===state.project)||state.projects[0];
const isMain=()=>state.project==='ai-workforce';
const features=[{id:'f35',name:'Bauen aus der Akte',description:'Aus einer Feature-Beschreibung direkt einen klaren Auftrag machen.',type:'Feature',priority:'P1',status:'Abnahme offen'},{id:'f36',name:'Passende Fähigkeiten empfehlen',description:'Jarvis schlägt geeignete Werkzeuge vor und erklärt, warum sie passen.',type:'Feature',priority:'P2',status:'Geplant'},{id:'f744',name:'Fehler verständlich erklären',description:'Eine klare Ursache und ein hilfreicher nächster Schritt bei Problemen.',type:'Verbesserung',priority:'P1',status:'Offen'},{id:'b12',name:'Fehlende Nutzungsdaten kennzeichnen',description:'Ein unbekannter Verbrauch darf nicht als null dargestellt werden.',type:'Fehler',priority:'P1',status:'Offen'}];
const capabilities=[{id:'claude',name:'Claude Code',category:'Worker',desc:'Entwickelt Funktionen und setzt klare Arbeitsaufträge im Projekt um.',state:'Freigegeben',role:'Umsetzung',icon:'work'},{id:'codex',name:'Codex',category:'Worker',desc:'Prüft Änderungen, untersucht Fehler und unterstützt die Umsetzung.',state:'Freigegeben',role:'Code Reviewer',icon:'shield'},{id:'review',name:'Code Review',category:'Skill',desc:'Prüft Qualität, Risiken und die vereinbarten Akzeptanzkriterien.',state:'Freigegeben',role:'Code Reviewer',icon:'search'},{id:'architecture',name:'Architekturberatung',category:'Skill',desc:'Klärt technische Entscheidungen vor einer umfangreichen Änderung.',state:'Freigegeben',role:'Architect',icon:'spark'},{id:'browser',name:'Browser-Prüfung',category:'Skill',desc:'Überprüft Bedienung und Darstellung direkt im Browser.',state:'Verfügbar',role:'Prüfung',icon:'home'},{id:'mcp',name:'Externe Verbindungen',category:'MCP',desc:'Bindet zusätzliche Dienste mit ausdrücklich erteiltem Zugriff an.',state:'Nicht verbunden',role:'Externe Quellen',icon:'folder'}];
function shell(){
$('#sidebar').innerHTML=`<a class="brand" href="#/uebersicht"><strong>JARVIS</strong><small>AI WORKFORCE</small></a><nav aria-label="Hauptnavigation">${[['uebersicht','home','Übersicht'],['projekte','folder','Projekte'],['arbeit','work','Arbeit'],['faehigkeiten','chart','Fähigkeiten'],['jarvis','chat','Jarvis']].map(([p,i,n])=>`<a href="#/${p}" data-nav="${p}">${icon(i)}${n}</a>`).join('')}</nav><img class="side-art" src="assets/gear.png" alt=""><div class="side-bottom"><a href="#/nutzung">${icon('chart')}Nutzung</a><a href="#/einstellungen">${icon('settings')}Einstellungen</a><a class="profile" href="#/einstellungen"><span class="avatar">S</span><span>Stefan<small class="subtle" style="display:block;font-size:10px">Dein persönliches Atelier</small></span></a></div>`;
$('#topbar').innerHTML=`<div class="top-left">${button(icon('menu'),'menu','icon-button mobile-menu','aria-label="Navigation öffnen"')}<span class="eyebrow">Projekt</span><select aria-label="Aktives Projekt" id="project-select" class="project-picker">${state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===state.project?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="top-right"><span class="availability"><span class="dot"></span>${state.runActive?'Eine Ausführung läuft':'Bereit, wenn du es bist'}</span><span class="demo-label">DESIGNVORSCHAU</span><a href="#/entscheidungen" aria-label="Offene Entscheidungen">${icon('alert')}</a></div>`;
}
function overview(){
const done=state.accepted;
return `<section class="hero"><img class="hero-art" src="assets/armillary.png" alt=""><img class="hero-face" src="assets/face.png" alt="Jarvis – wache jadefarbene Augen und ein feines Grinsen"><div class="hero-copy"><h1>AI Workforce</h1><div class="recent"><div class="eyebrow">${isMain()?'Zuletzt bearbeitet':'Dein aktives Projekt'}</div><h2>${isMain()?'Bauen aus der Akte':esc(project().name)}</h2><p>${isMain()?(done?'Umgesetzt · Von dir abgenommen':'Umgesetzt · Abnahme offen'):'Dein nächster Schritt: einen Auftrag beschreiben'}</p>${status(isMain()?(done?'Abgeschlossen':'Bereit für deine Prüfung'):'Bereit für deine Idee')}<br>${link(`${isMain()?'Ergebnis ansehen':'Auftrag beschreiben'} ${icon('arrow')}`,isMain()?'abnahme/f35':'auftrag/neu','text-link')}</div></div></section><section class="overview-bottom"><div class="section-label"><h2>Alles Wichtige. Auf einen Blick.</h2>${link('Projekt öffnen →','projekt/'+state.project,'')}</div><div class="grid cols-3">${link(`<div class="eyebrow">Deine Entscheidung</div><h3>${done?'Ergebnis abgenommen':isMain()?'Eine Abnahme wartet':'Bereit zum Start'}</h3><p>${done?'Bauen aus der Akte ist abgeschlossen.':isMain()?'Die Umsetzung ist geprüft. Du gibst das letzte Wort.':'Beschreibe, was du als Nächstes erreichen möchtest.'}</p><div class="card-footer"><span>${done?'Verlauf ansehen':'Nächster Schritt'}</span>${icon('arrow')}</div>`,isMain()?'abnahme/f35':'auftrag/neu','panel link-card')}${link(`<div class="eyebrow">Aktuelle Arbeit</div><h3>${state.runActive?'Umsetzung läuft':isMain()?'Alles an seinem Platz':'Noch keine Arbeit gestartet'}</h3><p>${state.runActive?'Jarvis arbeitet an deinem freigegebenen Auftrag.':'Keine Ausführung aktiv. Neue Arbeit startet erst nach deiner Freigabe.'}</p><div class="card-footer"><span>Arbeit ansehen</span>${icon('arrow')}</div>`,'arbeit','panel link-card')}${link(`<div class="eyebrow">Dein nächstes Ziel</div><h3>${isMain()?'Fähigkeiten gezielt einsetzen':'Deine erste Idee'}</h3><p>${isMain()?'Passende Werkzeuge vorschlagen und ihren Einsatz nachvollziehbar machen.':'Jarvis hilft dir dabei, aus deiner Idee einen klaren Auftrag zu machen.'}</p><div class="card-footer"><span>${isMain()?'Roadmap ansehen':'Mit Jarvis besprechen'}</span>${icon('arrow')}</div>`,isMain()?'projekt/ai-workforce/roadmap':'jarvis','panel link-card')}</div></section>`;
}
function projectsPage(){return heading('Dein Atelier','Projekte','Jedes Projekt hat seine eigene Arbeit, seine Entscheidungen und seinen Kontext.',link(`${icon('plus')}Neues Projekt`,'projekt/neu','button primary'))+`<div class="grid cols-2">${state.projects.map((p,i)=>link(`<div class="inline" style="justify-content:space-between"><span class="icon-badge">${icon('folder')}</span>${p.id===state.project?status('Aktives Projekt'):status('Bereit','neutral')}</div><h2>${esc(p.name)}</h2><p>${esc(p.description)}</p><div class="card-footer"><span>${p.id==='ai-workforce'?(state.accepted?'Letztes Ergebnis abgenommen':'1 Ergebnis wartet auf Abnahme'):'Bereit für deinen nächsten Auftrag'}</span>${icon('arrow')}</div>`,'projekt/'+p.id,'panel link-card')).join('')}</div>`;}
function projectPage(id,tab='ueberblick'){
const p=state.projects.find(p=>p.id===id);if(!p)return notFound();
const main=id==='ai-workforce';
return back('Alle Projekte','projekte')+heading('Projekt',esc(p.name),esc(p.description),link(`${icon('plus')}Auftrag anlegen`,'auftrag/neu','button primary'))+`<div class="tabs">${[['ueberblick','Überblick'],['roadmap','Roadmap'],['akte','Projektakte']].map(([t,n])=>link(n,`projekt/${id}/${t}`,t===tab?'active':'')).join('')}</div>`+(tab==='roadmap'?`<div class="note"><strong>Die Richtung ist klar.</strong> Die Roadmap zeigt vereinbarte Ziele. Erledigte Arbeitsschritte sind kein Prozentwert für den Fertigstellungsgrad eines Projekts.</div><div class="roadmap">${(main?[['01','Verlässlich arbeiten','In Umsetzung',[['Bauen aus der Akte',state.accepted?'Abgenommen':'Abnahme offen','arbeit/f35'],['Fehler verständlich erklären','Offen','arbeit/f744']]],['02','Fähigkeiten gezielt nutzen','Geplant',[['Passende Fähigkeiten empfehlen','Geplant','arbeit/f36'],['Verwendete Werkzeuge nachvollziehen','Geplant','faehigkeiten/empfehlungen']]],['03','Ergebnisse erlebbar machen','Geplant',[['Produkt öffnen & Vorschau','In Entwicklung','produkt']]]]:[['01','Eine gute Grundlage','Offen',[['Erstes Ziel mit dem Coach klären','Noch offen','jarvis/coach']]]]).map(([n,title,s,fs])=>`<div class="milestone"><div class="eyebrow">Etappe ${n}<p style="margin-top:10px">${status(s,s==='Geplant'?'neutral':'')}</p></div><div><h3>${title}</h3>${fs.map(([name,s,path])=>link(`<span>${name}</span><span class="row-meta">${s} →</span>`,path,'feature')).join('')}</div></div>`).join('')}</div>`:tab==='akte'?`<div class="split"><section><h2>Die Grundlage deiner Arbeit</h2><p class="subtle">Ziele, Feature-Beschreibungen und Befunde an einem Ort.</p><div class="line-list">${(main?[['Vision & Projektziel','Warum es dieses Projekt gibt.','jarvis/coach'],['Bauen aus der Akte','Feature F35 · umgesetzt','arbeit/f35'],['Passende Fähigkeiten empfehlen','Feature F36 · geplant','arbeit/f36'],['Offene Befunde','Fehler und Verbesserungen','arbeit/befunde']]:[['Projektziel formulieren','Gemeinsam mit dem Product Coach','jarvis/coach']]).map(([t,d,path])=>link(`<div><h3>${t}</h3><p>${d}</p></div>${icon('arrow')}`,path,'list-row')).join('')}</div><details><summary>Ordner & technische Angaben</summary><p>Projekt-ID: <code>${esc(p.id)}</code></p><p>Lokaler Zielordner: <code>${esc(p.folder)}</code></p><p class="subtle">Die Vorschau liest keine lokalen Dateien.</p></details></section><aside class="summary"><h3>Von der Idee zur Arbeit</h3><p class="subtle">Ein Feature beschreibt das Ziel. Ein Auftrag beschreibt die konkrete Arbeit. Du entscheidest, wann sie beginnt.</p>${link('Idee mit Coach klären →','jarvis/coach','text-link')}</aside></div>`:`<div class="split"><section><div class="grid cols-2"><div class="panel"><div class="eyebrow">Projektstand</div><h3>${main?'Verlässlich arbeiten':'Ziel klären'}</h3><p>${main?'Die erste Etappe ist in Umsetzung. Eine Funktion wartet auf deine Entscheidung.':'Ein gemeinsames Verständnis ist der beste Anfang.'}</p>${link('Roadmap ansehen →',`projekt/${id}/roadmap`,'text-link')}</div><div class="panel"><div class="eyebrow">Nächster Schritt</div><h3>${main?(state.accepted?'Nächstes Feature planen':'Ergebnis abnehmen'):'Idee besprechen'}</h3><p>${main?'Du entscheidest, ob das Ergebnis deinen Erwartungen entspricht.':'Der Coach führt dich mit wenigen Fragen zu einem klaren Ziel.'}</p>${link(main?'Ergebnis ansehen →':'Gespräch beginnen →',main?'abnahme/f35':'jarvis/coach','text-link')}</div></div><div class="section-label"><h2>Zuletzt im Projekt</h2></div>${main?`<ol class="timeline"><li class="done"><h3>Bauen aus der Akte umgesetzt</h3><p>Der Code wurde entwickelt und anschließend geprüft.</p><small>Heute · 10:42</small></li><li class="done"><h3>Code Review abgeschlossen</h3><p>Bereit zur Abnahme. Die Entscheidung liegt bei dir.</p><small>Heute · 11:08</small></li><li class="${state.accepted?'done':'current'}"><h3>${state.accepted?'Von dir abgenommen':'Deine Abnahme steht aus'}</h3>${link('Ergebnis ansehen →','abnahme/f35','text-link')}</li></ol>`:empty('Platz für etwas Neues','Lege deinen ersten Auftrag an oder kläre das Ziel mit dem Coach.',link('Zum Coach','jarvis/coach','button primary'))}</section><aside class="summary"><h3>Projektkontext</h3><dl><dt>Projekt</dt><dd>${esc(p.name)}</dd><dt>Aktive Ausführung</dt><dd>${state.runActive?'Eine Arbeit läuft':'Keine'}</dd><dt>Verantwortung</dt><dd>Stefan · letzte Entscheidung</dd></dl><div style="margin-top:26px">${link('Produkt & Vorschau →','produkt','text-link')}</div><img class="rail-art" src="assets/armillary.png" alt=""></aside></div>`);
}
function newProject(){return back('Projekte','projekte')+heading('Ein neuer Anfang','Woran möchtest du arbeiten?','Gib deinem Projekt einen Namen und einen Ort. Alles Weitere klären wir Schritt für Schritt.')+`<form class="form" id="new-project"><label class="field">Projektname<input name="name" required maxlength="70" placeholder="Zum Beispiel: Mein Haushaltsbuch" autofocus></label><label class="field">Was möchtest du erreichen? <span class="subtle">Optional</span><textarea name="description" placeholder="Eine kurze Idee genügt."></textarea></label><label class="field">Lokaler Zielordner<input name="folder" required placeholder="/projekte/mein-haushaltsbuch"><small>Hier wird später dein Projekt angelegt. In dieser Vorschau wird kein Ordner erstellt.</small></label><details><summary>Technische Kennung anpassen</summary><label class="field">Projekt-ID<input name="id" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" placeholder="Wird aus dem Namen erzeugt"><small>Kleinbuchstaben, Zahlen und Bindestriche. Nachträglich nicht ändern.</small></label></details><div class="action-row" style="margin-top:28px"><button class="button primary" type="submit">Projekt anlegen ${icon('arrow')}</button>${link('Abbrechen','projekte')}</div></form>`;}
function projectReady(id){const p=state.projects.find(p=>p.id===id)||project();return heading('Gut vorbereitet','Dein Projekt hat einen Platz.','Als Nächstes klärst du das Ziel mit dem Coach. Technische Einrichtung kannst du bei Bedarf nachlesen.')+`<div class="form"><div class="panel"><span class="icon-badge">${icon('folder')}</span><h2>${esc(p.name)}</h2><p>${esc(p.description||'Bereit für deinen ersten Gedanken.')}</p>${link('Mit dem Coach starten →','jarvis/coach','button primary')}</div><details><summary>Einrichtung: Git-Befehle zum Kopieren</summary><p class="subtle">Führe diese Befehle selbst im Zielordner aus. Jarvis führt hier keine Git-Befehle aus.</p><pre>git init\ngit add .\ngit commit -m "Projekt starten"</pre>${button('Befehle kopieren','copy-git')}</details><div style="margin-top:25px">${link('Zum Projekt →','projekt/'+p.id,'text-link')}</div></div>`;}
function workPage(tab='auftraege'){
return heading('Von der Idee zum Ergebnis','Arbeit','Sieh, was gerade entsteht, was auf dich wartet und was bereits erledigt ist.',link(`${icon('plus')}Auftrag anlegen`,'auftrag/neu','button primary'))+`<div class="tabs">${[['auftraege','Aufträge'],['features','Features'],['befunde','Befunde'],['verlauf','Ausführungen']].map(([t,n])=>link(n,'arbeit/'+t,t===tab?'active':'')).join('')}</div>`+(!isMain()&&!state.tasks.some(t=>t.project===state.project)?empty('Hier beginnt deine nächste Arbeit.','Ein verständliches Ziel reicht für den Anfang. Jarvis bereitet die nächsten Schritte mit dir vor.',link('Auftrag beschreiben','auftrag/neu','button primary')):tab==='features'||tab==='befunde'?`<div class="filters"><input id="work-search" aria-label="Arbeit durchsuchen" placeholder="${tab==='features'?'Feature':'Befund'} suchen …" value="${esc(state.search)}"><select id="work-filter" aria-label="Nach Status filtern">${['Alle','Offen','Abnahme offen','Geplant'].map(x=>`<option ${state.filter===x?'selected':''}>${x}</option>`).join('')}</select></div><div id="work-results">${workResults(tab)}</div>`:tab==='verlauf'?`<div class="note"><strong>Eine Ausführung ist ein einzelner Arbeitsschritt.</strong> Zum Beispiel die Umsetzung oder ein Code Review. Mehrere Ausführungen gehören zu einem Auftrag. ${help('Im technischen System heißen diese Arbeitsschritte „Runs“. Ein erfolgreicher Run bedeutet noch keine Abnahme des Ergebnisses.')}</div><div class="line-list">${[['review','Code Review','Codex · Code Reviewer','Erfolgreich'],['build','Bauen aus der Akte','Claude Code · Umsetzung','Erfolgreich'],['failed','Browser-Prüfung','Codex · Prüfung','Fehlgeschlagen']].map(([id,t,d,s])=>link(`<div><h3>${t}</h3><p>${d}</p></div><div class="row-end">${status(s,id==='failed'?'red':'')}<span class="row-meta">Heute ${icon('arrow')}</span></div>`,'ausfuehrung/'+id,'list-row')).join('')}</div>`:`${state.runActive?`<div class="note"><strong>Eine Arbeit läuft.</strong> Es kann insgesamt nur eine Ausführung gleichzeitig laufen – auch über Projektgrenzen hinweg.</div>`:''}<div class="line-list">${state.tasks.filter(t=>t.project===state.project).map(t=>link(`<div><h3>${esc(t.title)}</h3><p>Neuer Auftrag · Umsetzung → Code Review</p></div><div class="row-end">${status(state.runActive&&state.activeTaskId===t.id?'In Arbeit':t.status==='stopped'?'Gestoppt':'Freigabe erforderlich','amber')}${icon('arrow')}</div>`,'workflow/'+t.id,'list-row')).join('')}${isMain()?link(`<div><h3>Bauen aus der Akte</h3><p>Feature F35 · Umsetzung und Code Review abgeschlossen</p></div><div class="row-end">${status(state.accepted?'Abgenommen':'Deine Abnahme fehlt',state.accepted?'':'amber')}${icon('arrow')}</div>`,'workflow/f35','list-row'):''}${state.iteration&&isMain()?link(`<div><h3>Bauen aus der Akte · Anpassung ${state.iteration}</h3><p>Automatisch angelegt · Start erfordert deine Freigabe</p></div><div class="row-end">${status('Freigabe erforderlich','amber')}${icon('arrow')}</div>`,'workflow/anpassung','list-row'):''}${isMain()?link(`<div><h3>Fehler verständlich erklären</h3><p>Rückfrage: Welche Fehlermeldung soll zuerst verbessert werden?</p></div><div class="row-end">${status(state.questionAnswered?'Antwort hinterlegt':'Deine Antwort fehlt','amber')}${icon('arrow')}</div>`,'workflow/klaerung','list-row'):''}</div><div class="section-label"><h2>So arbeitet deine Workforce</h2></div><div class="grid cols-3">${[['01','Auftrag klären','Du beschreibst das Ziel. Jarvis bereitet einen passenden Ablauf vor.'],['02','Bewusst starten','Du prüfst den Vorschlag und gibst den nächsten Schritt frei.'],['03','Ergebnis abnehmen','Nach Umsetzung und Prüfung entscheidest du über das Ergebnis.']].map(([n,t,d])=>`<div class="panel"><div class="eyebrow">${n}</div><h3>${t}</h3><p>${d}</p></div>`).join('')}</div>`);
}
function workResults(tab){let arr=features.filter(f=>(tab==='features'?f.type==='Feature':f.type!=='Feature')&&(state.filter==='Alle'||f.status===state.filter)&&f.name.toLowerCase().includes(state.search.toLowerCase()));return arr.length?`<div class="line-list">${arr.map(f=>link(`<div class="inline"><span class="number">${f.type==='Feature'?'◇':'!'}</span><div><h3>${f.name}</h3><p>${f.description}</p></div></div><div class="row-end"><span class="tag">${f.priority}</span>${status(f.status,f.status==='Offen'?'amber':'neutral')}${icon('arrow')}</div>`,'arbeit/'+f.id,'list-row')).join('')}</div>`:empty('Keine passenden Einträge','Passe den Suchbegriff oder den Filter an.');}
function featurePage(id){const f=features.find(x=>x.id===id);if(!f)return notFound();return back(f.type==='Feature'?'Features':'Befunde','arbeit/'+(f.type==='Feature'?'features':'befunde'))+heading(`${f.type} · ${f.id.toUpperCase()}`,f.name,f.description,id==='f35'?link('Ergebnis ansehen','abnahme/f35','button primary'):button(f.type==='Feature'?'Als Auftrag vorbereiten':'Bearbeitung vorbereiten','build-feature','button primary',`data-id="${id}"`))+`<div class="split"><section><h2>${f.type==='Feature'?'Das soll möglich werden':'Was verbessert werden soll'}</h2><p class="subtle">${id==='f35'?'Eine vorhandene Feature-Datei wird zu einem nachvollziehbaren Arbeitsauftrag. Jarvis schlägt die zuständigen Rollen und den nächsten erlaubten Schritt vor. Du behältst die Kontrolle über den Start.':id==='f36'?'Geeignete Fähigkeiten werden passend zur Aufgabe vorgeschlagen. Jede Empfehlung nennt einen verständlichen Grund. Vor dem Start entscheidest du, welche Fähigkeiten freigegeben werden.':id==='b12'?'Wenn Nutzungsdaten einer Ausführung fehlen, muss die Anzeige „Nicht erfasst“ zeigen. Ein unbekannter Verbrauch darf nicht wie kostenloses oder verbrauchsloses Arbeiten aussehen.':'Fehler sollen Ursache, Auswirkung und einen konkreten nächsten Schritt zeigen. Der rohe technische Bericht bleibt bei Bedarf verfügbar.'}</p><h2 style="margin-top:32px">Woran wir das Ergebnis erkennen</h2><ul class="checklist">${(id==='f35'?['Ein Auftrag lässt sich aus einer Feature-Datei vorbereiten.','Der vorgeschlagene Ablauf ist vor dem Start sichtbar.','Jeder schreibende Schritt benötigt eine Freigabe.']:id==='f36'?['Empfehlungen enthalten eine Begründung.','Freigegebene und tatsächlich verwendete Werkzeuge sind unterscheidbar.','Es wird nichts ungefragt installiert oder aktiviert.']:['Die Ursache ist in verständlicher Sprache sichtbar.','Unvollständige Informationen bleiben als solche erkennbar.','Ein sinnvoller nächster Schritt ist direkt erreichbar.']).map(t=>`<li><span class="checkmark">${id==='f35'?'✓':'○'}</span><span>${t}</span></li>`).join('')}</ul>${id==='f36'?`<div class="note amber"><strong>In Entwicklung.</strong> Diese Ansicht zeigt den geplanten Ablauf. Katalog-Installation und automatische Empfehlungen sind noch keine verfügbare Produktfunktion.</div>`:''}<details><summary>${f.type==='Feature'?'Datei & technische Referenz':'Fundstelle, Auswirkung & Abhilfe'}</summary><p>Datei: <code>${f.type==='Feature'?'features/'+id+'.md':'src/ui/verbrauch.js'}</code></p><p class="subtle">${f.type==='Feature'?'Die Beschreibung bleibt die fachliche Grundlage des Auftrags.':'Auswirkung: fehlende Messwerte können falsch interpretiert werden. Abhilfe: einen expliziten unbekannten Zustand verwenden.'}</p></details></section><aside class="summary"><h3>Einordnung</h3><dl><dt>Status</dt><dd>${status(f.status,'amber')}</dd><dt>Priorität</dt><dd>${f.priority} ${help('P0: kritisch. P1: wichtig. P2: regulär. Die Priorität ist kein automatischer Startbefehl.')}</dd><dt>Projekt</dt><dd>${esc(project().name)}</dd><dt>Nächster Schritt</dt><dd>${id==='f35'?'Deine Abnahme':'Auftrag vorbereiten und freigeben'}</dd></dl><img class="rail-art" src="assets/gear.png" alt=""></aside></div>`;}
function newTask(){const d=state.taskDraft||{};return back('Arbeit','arbeit')+heading('Ein klarer Auftrag','Was soll deine Workforce erledigen?','Beschreibe das gewünschte Ergebnis. Jarvis bereitet daraus einen Ablauf vor.')+`<div class="stepper"><span class="active"><b>1</b>Auftrag</span><span><b>2</b>Ablauf prüfen</span><span><b>3</b>Freigeben</span></div><form id="new-task" class="form"><label class="field">Titel<input name="title" required maxlength="120" placeholder="Was möchtest du verbessern?" value="${esc(d.title||'')}"></label><label class="field">Gewünschtes Ergebnis<textarea name="text" required placeholder="Was soll anschließend möglich sein? Was ist dir dabei wichtig?">${esc(d.text||'')}</textarea></label><details ${d.evidence?'open':''}><summary>Kontext hinzufügen · optional</summary><label class="field">Relevante Dateien oder Nachweise<textarea name="evidence" placeholder="Zum Beispiel: features/f35.md">${esc(d.evidence||'')}</textarea><small>Ein Pfad pro Zeile. Es werden hier keine Dateien hochgeladen.</small></label></details><div class="note">Rolle und Arbeitsweise werden aus dem Projektkontext vorgeschlagen. Du prüfst den Ablauf, bevor etwas startet.</div><div class="action-row"><button type="submit" class="button primary">Ablauf vorbereiten ${icon('arrow')}</button>${link('Lieber mit dem Coach besprechen','jarvis/coach','button')}</div></form>`;}
function taskReview(){const t=state.taskDraft;if(!t)return newTask();return back('Auftrag bearbeiten','auftrag/neu')+heading('Deine Freigabe','Ein guter Plan für deine Aufgabe.','Prüfe Ziel, Rollen und Kontext. Erst deine Freigabe startet die Umsetzung.')+`<div class="stepper"><span><b>✓</b>Auftrag</span><span class="active"><b>2</b>Ablauf prüfen</span><span><b>3</b>Freigeben</span></div><div class="split"><section><h2>${esc(t.title)}</h2><p class="subtle">${esc(t.text)}</p><div class="section-label"><h2>Vorgeschlagener Ablauf</h2></div><ol class="timeline"><li class="current"><h3>1. Umsetzung · Claude Code</h3><p>Entwickelt die Änderung anhand deines Auftrags.</p><small>Start nur mit deiner Freigabe</small></li><li><h3>2. Code Review · Codex</h3><p>Prüft Ergebnis, Risiken und Akzeptanzkriterien.</p><small>Separate Freigabe vor dem nächsten Schritt</small></li><li><h3>3. Deine Abnahme</h3><p>Du entscheidest, ob das Ergebnis passt.</p></li></ol>${t.evidence?`<details><summary>Mitgegebener Kontext</summary><pre>${esc(t.evidence)}</pre></details>`:''}<div class="note ${state.runActive?'amber':''}">${state.runActive?'Eine andere Ausführung läuft bereits. Warte auf ihr Ende oder stoppe sie bewusst.':'Diese Freigabe gilt nur für den nächsten Umsetzungsschritt. Weitere Schritte starten nicht automatisch.'}</div><div class="action-row">${button('Umsetzung freigeben & starten','start-task','button primary',state.runActive?'disabled':'')}${button('Nur als Auftrag speichern','save-task')}</div></section><aside class="summary"><h3>Vor dem Start</h3><dl><dt>Projekt</dt><dd>${esc(project().name)}</dd><dt>Vorgeschlagene Rolle</dt><dd>Umsetzung</dd><dt>Worker</dt><dd>Claude Code</dd><dt>Arbeitsweise</dt><dd>Projektvorgabe · kein Modell-Override</dd></dl><details><summary>Warum dieser Ablauf?</summary><p class="subtle">Eine klar eingegrenzte Änderung benötigt Umsetzung und eine unabhängige Prüfung. Bei hohem Architektur-Risiko werden Architect und Architekturberatung vorgeschaltet.</p></details>${link('Geplante Fähigkeitsempfehlungen →','faehigkeiten/empfehlungen','text-link')}</aside></div>`;}
function workflowPage(id){const task=state.tasks.find(t=>t.id===id)||(id==='neu'?state.tasks.filter(t=>t.project===state.project).at(-1):null);if(task)state.selectedTaskId=task.id;const taskRunning=state.runActive&&(task?state.activeTaskId===task.id:state.activeWorkflowId===id);const taskStopped=task?task.status==='stopped':state.runStopped&&state.activeWorkflowId===id;const complete=id==='f35',clarify=id==='klaerung',invalid=id==='ungueltig',adjust=id==='anpassung';const title=complete?'Bauen aus der Akte':clarify?'Fehler verständlich erklären':invalid?'Ablauf prüfen':adjust?`Bauen aus der Akte · Anpassung ${state.iteration||1}`:task?.title||'Neuer Auftrag';return back('Alle Aufträge','arbeit')+heading('Auftrag & Ablauf',esc(title),'Jeder Schritt hat einen klaren Zweck. Du behältst die Kontrolle.',complete?link('Zur Abnahme','abnahme/f35','button primary'):'')+`<div class="split"><section>${invalid&&!state.repair?`<div class="note red"><strong>! Dieser Ablauf ist nicht gültig.</strong><p>Die gespeicherte Version entspricht nicht mehr der aktuellen Ablaufstruktur. Start und Freigabe sind gesperrt.</p>${button('Ablauf reparieren','repair','button primary')}</div>`:clarify&&!state.questionAnswered?`<div class="note amber"><strong>Jarvis braucht deine Entscheidung.</strong><p>Welche Fehlermeldung sollen wir zuerst verständlicher machen?</p>${button('Rückfrage beantworten','answer','button primary')}</div>`:adjust?`<div class="note amber"><strong>Automatisch angelegt · Iteration ${state.iteration||1}/3</strong><p>Start erfordert deine Freigabe. Grund: ${esc(state.decision?.reason||'Ergebnis nachbessern.')}</p></div>`:taskStopped?`<div class="note amber"><strong>Arbeit gestoppt.</strong> Es wird nichts weiter ausgeführt, bis du bewusst fortsetzt.</div>`:state.questionAnswered&&clarify?`<div class="note"><strong>Deine Antwort wurde hinterlegt.</strong> ${esc(state.answer||'')}</div>`:''}${state.runActive&&!taskRunning?'<div class="note amber">Eine andere Ausführung läuft. Dieser Auftrag bleibt vorbereitet, bis die Workforce wieder frei ist.</div>':''}<h2>Der Weg zum Ergebnis</h2><ol class="timeline"><li class="${complete?'done':taskRunning?'current':''}"><h3>Umsetzung</h3><p>Claude Code entwickelt die vereinbarte Funktion.</p><small>${complete?'Abgeschlossen · heute, 10:42':taskRunning?'Läuft · Beispielausführung':'Wartet auf deine Freigabe'}</small>${complete?`<p>${link('Ausführung ansehen →','ausfuehrung/build','text-link')}</p>`:''}</li><li class="${complete?'done':''}"><h3>Unabhängiges Code Review</h3><p>Codex prüft Qualität, Risiken und Anforderungen.</p><small>${complete?'Abgeschlossen · heute, 11:08':'Wartet auf die Umsetzung'}</small></li><li class="${complete?'current':''}"><h3>Deine Abnahme</h3><p>${state.accepted&&complete?'Du hast das Ergebnis abgenommen.':'Ein technischer Erfolg wird erst durch deine Entscheidung zu einem abgenommenen Ergebnis.'}</p></li></ol><div class="action-row">${complete?link('Ergebnis prüfen →','abnahme/f35','button primary'):taskRunning?button('Ausführung stoppen','stop-run','button danger'):button(taskStopped?'Fortsetzung vorbereiten':'Nächsten Schritt freigeben','start-workflow','button primary',((clarify&&!state.questionAnswered)||(invalid&&!state.repair))?'disabled':'')}${button('Ablauf erneut prüfen','validate')}</div><details><summary>Technischer Ablauf & Serverentscheidung</summary><pre>${esc(JSON.stringify({workflow:id,status:invalid&&!state.repair?'KLAERUNG_ERFORDERLICH':complete?'ABGESCHLOSSEN':taskRunning?'LAEUFT':taskStopped?'GESTOPPT':clarify&&!state.questionAnswered?'KLAERUNG_ERFORDERLICH':'WARTET_FREIGABE',naechster:{art:complete?'ABNAHME':invalid&&!state.repair?'REPARATUR':clarify&&!state.questionAnswered?'ANTWORT':'FREIGABE'}},null,2))}</pre><p class="subtle">Im Produkt legt die Serverentscheidung fest, welche Aktionen zulässig sind. Diese Vorschau simuliert sie.</p></details></section><aside class="summary"><h3>Auf einen Blick</h3><dl><dt>Status</dt><dd>${status(complete?(state.accepted?'Abgenommen':'Abnahme offen'):taskRunning?'In Arbeit':taskStopped?'Gestoppt':'Deine Entscheidung','amber')}</dd><dt>Projekt</dt><dd>${esc(project().name)}</dd><dt>Aktueller Schritt</dt><dd>${complete?'Deine Abnahme':clarify?'Klärung':'Umsetzung'}</dd><dt>Verantwortung</dt><dd>Stefan</dd></dl><img class="rail-art" src="assets/armillary.png" alt=""></aside></div>`;}
function acceptance(){return back('Zum Auftrag','workflow/f35')+heading('Dein letztes Wort','Passt das Ergebnis?','Bauen aus der Akte · Umsetzung und unabhängige Prüfung sind abgeschlossen.',status(state.accepted?'Von dir abgenommen':'Deine Abnahme fehlt',state.accepted?'':'amber'))+`<div class="split"><section><h2>Was sich verbessert hat</h2><p class="subtle">Du kannst aus einer vorhandenen Feature-Beschreibung einen Auftrag vorbereiten. Der Ablauf wird verständlich vorgeschlagen und startet erst nach deiner ausdrücklichen Freigabe.</p><div class="note"><strong>✓ Empfehlung des Code Reviewers: bereit zur Abnahme.</strong><br>Die vereinbarten Kriterien sind erfüllt. Du prüfst jetzt, ob das Ergebnis auch deinen Erwartungen entspricht.</div><div class="section-label"><h2>Vereinbart & überprüft</h2></div><ul class="checklist">${[['Auftrag aus Feature anlegen','Nachweis: Feature F35 erfolgreich in einen Auftrag überführt.'],['Ablauf vor dem Start anzeigen','Nachweis: Umsetzung und Code Review werden vor der Freigabe gezeigt.'],['Kein Start ohne Freigabe','Nachweis: schreibende Aktionen bleiben bis zur Freigabe gesperrt.']].map(([t,d])=>`<li><span class="checkmark">✓</span><div>${t}<p>${d}</p></div></li>`).join('')}</ul><details><summary>Geänderte Dateien · 4 Dateien</summary><div class="table-wrap"><table><thead><tr><th>Datei</th><th>Änderung</th></tr></thead><tbody><tr><td>src/features/auftrag.js</td><td>Neu</td></tr><tr><td>src/api/features.js</td><td>Geändert</td></tr><tr><td>src/ui/workboard.js</td><td>Geändert</td></tr><tr><td>tests/feature-auftrag.test.js</td><td>Neu</td></tr></tbody></table></div><p class="subtle">Beispielhafte Dateizusammenfassung · keine Dateien gelöscht oder umbenannt.</p></details><details><summary>Prüfbericht & Nachweise</summary><p class="subtle">Codex hat den Ablauf geprüft. Ergebnis: bereit. Umfang entspricht dem Auftrag. Keine offenen blockierenden Befunde im Beispielbericht.</p>${link('Code Review öffnen →','ausfuehrung/review','text-link')}</details>${state.decision?`<div class="note"><strong>Deine Entscheidung: ${esc(state.decision.label)}</strong><br>${esc(state.decision.reason)}</div>`:''}${!state.accepted?`<div class="section-label"><h2>Deine Entscheidung</h2></div><p class="subtle">Eine kurze Begründung hält nachvollziehbar fest, warum du so entscheidest.</p><div class="action-row">${button('Ergebnis abnehmen','decision','button primary','data-kind="accept"')}${button('Anpassung wünschen','decision','button','data-kind="adjust"')}${button('Ablehnen','decision','button danger','data-kind="reject"')}</div>${state.iteration>=3?'<div class="note amber">Drei automatische Anpassungsaufträge wurden angelegt. Weitere Arbeit benötigt einen neuen, ausdrücklich angelegten Auftrag.</div>':''}`:link('Zurück zur Übersicht →','uebersicht','button primary')}</section><aside class="summary"><h3>Das Ergebnis</h3><dl><dt>Feature</dt><dd>Bauen aus der Akte</dd><dt>Umsetzung</dt><dd>Claude Code</dd><dt>Prüfung</dt><dd>Codex · Code Reviewer</dd><dt>Review-Urteil</dt><dd>${status('Bereit')}</dd><dt>Deine Abnahme</dt><dd>${state.accepted?'Erteilt':'Noch offen'}</dd></dl><div class="note">„Ausführung erfolgreich“ bedeutet, dass ein Arbeitsschritt beendet ist. Deine Abnahme ist eine eigene Entscheidung.</div></aside></div>`;}
function runPage(id){const failed=id==='failed',review=id==='review';return back('Alle Ausführungen','arbeit/verlauf')+heading('Ein Arbeitsschritt',failed?'Browser-Prüfung':review?'Code Review':'Bauen aus der Akte',failed?'Die Ausführung konnte nicht abgeschlossen werden.':review?'Das Ergebnis wurde unabhängig geprüft.':'Die vereinbarte Funktion wurde umgesetzt.',status(failed?'Fehlgeschlagen':'Erfolgreich',failed?'red':''))+`<div class="split"><section>${failed?`<div class="note red"><strong>! Die Browser-Freigabe fehlte.</strong><p>Der Worker durfte den Browser nicht öffnen. Dein Projekt wurde durch diesen fehlgeschlagenen Schritt nicht verändert.</p><div class="action-row">${button('Fehler zur Kenntnis nehmen','acknowledge','button',state.acknowledged?'disabled':'')}${button('Fortsetzung vorbereiten','resume','button primary')}</div>${state.acknowledged?'<p>Mit Begründung bestätigt.</p>':''}</div>`:`<div class="note"><strong>${review?'Bereit zur Abnahme.':'Umsetzung abgeschlossen.'}</strong> ${review?'Du kannst das Ergebnis jetzt prüfen und darüber entscheiden.':'Das anschließende Code Review hat die Anforderungen geprüft.'}</div>`}<h2>Was passiert ist</h2><ol class="timeline"><li class="done"><h3>Auftrag übernommen</h3><p>Ziel und Kontext wurden dem Worker übergeben.</p><small>10:31 · Auftrag & Feature-Datei</small></li><li class="done"><h3>${review?'Änderungen geprüft':'Kontext geprüft'}</h3><p>${review?'Akzeptanzkriterien, Umfang und Risiken bewertet.':'Relevante Dateien gelesen und Vorgehen festgelegt.'}</p><small>10:33 · Prüfpunkt 1</small></li><li class="${failed?'current':'done'}"><h3>${failed?'Zugriff blockiert':review?'Review abgeschlossen':'Änderung umgesetzt & geprüft'}</h3><p>${failed?'Browserzugriff benötigt eine Freigabe.':review?'Urteil: bereit. Keine blockierenden Befunde.':'Die Funktion wurde implementiert und die vorgesehenen Prüfungen wurden ausgeführt.'}</p><small>${review?'11:08':'10:42'} · Ergebnis</small></li></ol>${!failed?link('Ergebnis & Abnahme →','abnahme/f35','button primary'):''}<details><summary>Auftrag, Kontext & Nachweise</summary><p>Ziel: ${failed?'Die Oberfläche im Browser prüfen.':'Aus einer Feature-Beschreibung einen Auftrag vorbereiten.'}</p><pre>features/f35.md\nAGENTS.md\nsrc/ui/workboard.js</pre></details><details><summary>Worker, Modell & Herkunft</summary><div class="table-wrap"><table><tbody><tr><th>Worker</th><td>${review||failed?'Codex':'Claude Code'}</td></tr><tr><th>Deklariertes Modell</th><td>Projektvorgabe</td></tr><tr><th>Beobachtetes Modell</th><td>Nicht erfasst</td></tr><tr><th>Quelle</th><td>Beispieldaten, keine Worker-Telemetrie</td></tr><tr><th>Arbeitsordner</th><td>/projekte/${esc(state.project)}</td></tr></tbody></table></div></details><details><summary>Technisches Protokoll</summary><pre>${failed?'stderr: permission denied: browser access\nexit_code: 1\nstdout_length: 0\nstderr_length: 39':'status: completed\nexit_code: 0\ncheckpoint: result_received\ntransport: local\nresult: success'}\nrun_id: demo-${esc(id)}\nlineage: workflow-f35</pre></details><details><summary>Tatsächlich verwendete Fähigkeiten <span class="tag planned">In Entwicklung</span></summary><p class="subtle">Diese geplante Ansicht wird beobachtete Skills und Subagenten aus der Ausführung zeigen. Ohne Nachweis wird keine Nutzung behauptet.</p></details></section><aside class="summary"><h3>Einordnung</h3><dl><dt>Auftrag</dt><dd>Bauen aus der Akte</dd><dt>Rolle</dt><dd>${review?'Code Reviewer':failed?'Prüfung':'Umsetzung'}</dd><dt>Worker</dt><dd>${review||failed?'Codex':'Claude Code'}</dd><dt>Ergebnis</dt><dd>${failed?'Zugriff fehlte':'Arbeitsschritt abgeschlossen'}</dd><dt>Abnahme</dt><dd>${state.accepted?'Erteilt':'Separat erforderlich'}</dd></dl></aside></div>`;}
function capabilitiesPage(tab='werkzeuge'){return heading('Deine Workforce','Fähigkeiten','Wer kann was – und was ist für deine Arbeit freigegeben?',link(`${icon('search')}Fähigkeit entdecken`,'faehigkeiten/scout','button'))+`<div class="tabs">${[['werkzeuge','Werkzeuge'],['rollen','Rollen & Besetzung'],['empfehlungen','Empfehlungen']].map(([t,n])=>link(n,'faehigkeiten/'+t,t===tab?'active':'')).join('')}</div>`+(tab==='rollen'?`<div class="note">Eine Rolle beschreibt die Verantwortung. Der zugewiesene Worker führt sie aus. Was tatsächlich verwendet wurde, steht später im jeweiligen Arbeitsschritt.</div><div class="line-list">${[['Jarvis','Orientierung, Status und nächste Schritte','Lokale Statuslogik / Gespräch'],['Product Coach','Ideen klären und einen tragfähigen Auftrag entwickeln','Coach-Konfiguration'],['Router','Den passenden Arbeitsablauf vorschlagen','Projektvorgabe'],['Architect','Architektur und Risiken klären','Claude Code'],['Umsetzung','Den freigegebenen Auftrag ausführen','Claude Code'],['Code Reviewer','Das Ergebnis unabhängig prüfen','Codex']].map(([r,d,w])=>`<div class="list-row"><div><h3>${r}</h3><p>${d}</p></div><div class="row-end"><span class="row-meta">${w}</span>${button('Details','role','button',`data-role="${r}" data-worker="${w}"`)}</div></div>`).join('')}</div><div class="note amber"><strong>Abdeckung im Beispiel:</strong> Kernrollen sind besetzt. Die Browser-Prüfung ist verfügbar, benötigt aber eine Freigabe für den Zugriff.</div>`:tab==='empfehlungen'?`<div class="split"><section><span class="tag planned">In Entwicklung · F36</span><h2 style="margin-top:22px">Die passenden Werkzeuge. Mit einem guten Grund.</h2><p class="subtle">So soll die Auswahl vor dem Start aussehen. Die Empfehlung aktiviert oder installiert nichts automatisch.</p><div class="panel"><div class="eyebrow">Beispielauftrag · Oberfläche verbessern</div><label class="check"><input type="checkbox" checked disabled><span><strong>Code Review</strong><br><span class="subtle">Prüft Qualität und die vereinbarten Anforderungen.</span></span></label><label class="check"><input type="checkbox" disabled><span><strong>Browser-Prüfung</strong><br><span class="subtle">Passt, weil Bedienung und Darstellung geändert werden.</span></span></label><div class="note amber">Entwurf der geplanten Auswahl · noch nicht mit dem Start verbunden.</div></div><details><summary>Geplanter Ablauf für neue Fähigkeiten</summary><ol><li>Kandidaten finden und Anwendbarkeit erklären.</li><li>Installation und Berechtigungen gesondert prüfen.</li><li>Fähigkeit für einen konkreten Auftrag freigeben.</li><li>Tatsächlich beobachtete Nutzung im Ergebnis zeigen.</li></ol></details></section><aside class="summary"><h3>Bewusst freigeben</h3><p class="subtle">„Empfohlen“, „verfügbar“, „freigegeben“ und „verwendet“ sind unterschiedliche Zustände.</p><img class="rail-art" src="assets/gear.png" alt=""></aside></div>`:`<div class="filters"><input id="cap-search" aria-label="Fähigkeiten suchen" placeholder="Eine Fähigkeit suchen …"><select id="cap-filter" aria-label="Fähigkeitstyp"><option>Alle Typen</option><option>Worker</option><option>Skill</option><option>MCP</option></select></div><div class="grid cols-3" id="cap-results">${capCards(capabilities)}</div><div class="note">${help('Verfügbar: bekannt und grundsätzlich nutzbar. Freigegeben: darf im vorgesehenen Rahmen eingesetzt werden. Verwendet: durch eine Ausführung tatsächlich nachgewiesen.')} <strong>Freigegeben bedeutet nicht gerade aktiv.</strong> Ob ein Werkzeug wirklich verwendet wurde, gehört zur jeweiligen Ausführung.</div>`);}
function capCards(arr){return arr.length?arr.map(c=>`<a class="panel link-card" href="#/faehigkeit/${c.id}"><div class="inline" style="justify-content:space-between"><span class="icon-badge">${icon(c.icon)}</span><span class="tag">${c.category}</span></div><h3>${c.name}</h3><p>${c.desc}</p><div class="card-footer">${status(c.state,c.state==='Freigegeben'?'':'neutral')}${icon('arrow')}</div></a>`).join(''):empty('Keine passende Fähigkeit','Versuche einen anderen Suchbegriff.');}
function capabilityDetail(id){const c=capabilities.find(x=>x.id===id);if(!c)return notFound();return back('Fähigkeiten','faehigkeiten')+heading(c.category,c.name,c.desc,status(c.state,c.state==='Freigegeben'?'':'neutral'))+`<div class="split"><section><h2>Wann diese Fähigkeit hilft</h2><p class="subtle">${c.desc} Sie wird gezielt in einem passenden Arbeitsablauf eingesetzt.</p><div class="grid cols-2"><div class="panel"><div class="eyebrow">Zuständigkeit</div><h3>${c.role}</h3><p>Die Verantwortung wird durch den Rollenvertrag festgelegt.</p></div><div class="panel"><div class="eyebrow">Verwendung</div><h3>Pro Auftrag nachvollziehbar</h3><p>Eine Freigabe allein beweist noch keine tatsächliche Nutzung.</p></div></div><details><summary>Freigabe & technische Herkunft</summary><p class="subtle">Quelle: lokaler Ressourcenkatalog des Projekts · Beispielkonfiguration.</p><p>Typ: ${c.category}<br>Status: ${c.state}<br>Projekt: ${esc(project().name)}</p></details><div class="note">Die Vorschau verändert keine installierten Werkzeuge oder Berechtigungen.</div>${link('Zugehörige Rollen ansehen →','faehigkeiten/rollen','text-link')}</section><aside class="summary"><h3>Bewusst eingesetzt</h3><p class="subtle">Jarvis schlägt den Ablauf vor. Du gibst die Arbeit frei.</p><img class="rail-art" src="assets/gear.png" alt=""></aside></div>`;}
function scout(){return back('Fähigkeiten','faehigkeiten')+heading('Scout','Was fehlt deiner Workforce?','Beschreibe eine Fähigkeit, nach der du suchst. Die Vorschau durchsucht einen kleinen Beispielkatalog.')+`<form id="scout-form" class="form"><label class="field">Gesuchte Fähigkeit<input name="query" required placeholder="Zum Beispiel: Webseiten im Browser prüfen"></label><button class="button primary" type="submit">Kandidaten finden ${icon('search')}</button></form><div id="scout-results" style="margin-top:35px"></div>`;}
function decisions(){if(!isMain())return heading('Dein Fokus','Was braucht dich?','Entscheidungen für '+esc(project().name))+empty('Noch keine offenen Entscheidungen.','Dieses Beispielprojekt hat noch keine Rückfragen, Abnahmen, Startprobleme oder wichtigen Befunde.',link('Auftrag anlegen','auftrag/neu','button primary'));const unknown=state.scenario==='unavailable',none=state.scenario==='empty';return heading('Dein Fokus','Was braucht dich?','Offene Entscheidungen, wichtige Befunde und Probleme an einem Ort.')+(unknown?`<div class="note amber"><strong>! Ein Teil der Daten ist nicht verfügbar.</strong><p>Der Status wichtiger Befunde konnte nicht geladen werden. Daher ist keine verlässliche Entwarnung möglich.</p>${button('Erneut laden','retry')}</div>`:'')+(none?empty('Für den Moment ist alles geklärt.','Alle vier Quellen wurden geprüft: wartende Aufträge, unbestätigte Fehler, Startprobleme und wichtige Befunde.',link('Zur Übersicht','uebersicht','button primary')):`<div class="line-list">${!state.accepted?link(`<div><div class="eyebrow">Wartender Auftrag</div><h3>Deine Abnahme für „Bauen aus der Akte“</h3><p>Die Umsetzung ist geprüft. Entscheide, ob das Ergebnis passt.</p></div>${icon('arrow')}`,'abnahme/f35','list-row'):''}${!state.questionAnswered?link(`<div><div class="eyebrow">Rückfrage</div><h3>Welche Fehlermeldung soll zuerst verbessert werden?</h3><p>Deine Antwort gibt der Arbeit eine klare Richtung.</p></div>${icon('arrow')}`,'workflow/klaerung','list-row'):''}${!state.acknowledged?link(`<div><div class="eyebrow">Unbestätigter Fehler</div><h3>Browser-Prüfung konnte nicht starten</h3><p>Der Browserzugriff war nicht freigegeben.</p></div>${icon('arrow')}`,'ausfuehrung/failed','list-row'):''}${!unknown?link(`<div><div class="eyebrow">Wichtiger Befund · P1</div><h3>Fehlende Nutzungsdaten kennzeichnen</h3><p>Unbekannte Messwerte dürfen nicht als null erscheinen.</p></div>${icon('arrow')}`,'arbeit/b12','list-row'):''}</div><div class="section-label"><h2>Die vier Quellen</h2></div><div class="grid cols-4">${[['Wartende Aufträge',(!state.accepted?1:0)+(!state.questionAnswered?1:0)],['Unbestätigte Fehler',state.acknowledged?0:1],['Startprobleme',0],['Wichtige Befunde',unknown?'Nicht verfügbar':1]].map(([t,n])=>`<div class="panel stat"><div class="eyebrow">${t}</div><strong ${unknown&&t==='Wichtige Befunde'?'style="font-size:20px;color:var(--amber)"':''}>${n}</strong><small>${n===0?'Geprüft · keine offenen Einträge':t==='Wichtige Befunde'?'P0 & P1':'Im aktiven Projekt'}</small></div>`).join('')}</div>`);}
function usage(){if(!isMain())return heading('Verständlich eingeordnet','Nutzung','Erfasste KI-Arbeit für '+esc(project().name))+empty('Noch keine Messwerte.','Für dieses Beispielprojekt liegen noch keine abgeschlossenen Ausführungen mit Nutzungsdaten vor.',link('Arbeit ansehen','arbeit'));const nums=state.usage==='7'?[12,9,3,420000,92000,180000,14000]:state.usage==='all'?[64,56,8,2480000,512000,1250000,64000]:[28,24,4,1260000,284000,680000,32000],fmt=n=>new Intl.NumberFormat('de-DE').format(n);return heading('Verständlich eingeordnet','Nutzung','Wie viel KI-Arbeit wurde erfasst? Ohne erfundene Kosten oder ein vermeintliches Restbudget.')+`<div class="tabs" aria-label="Zeitraum">${[['7','Letzte 7 Tage'],['30','Letzte 30 Tage'],['all','Gesamter Zeitraum']].map(([v,n])=>button(n,'usage',v===state.usage?'active':'',`data-value="${v}"`)).join('')}</div>${state.scenario==='unavailable'?`<div class="note amber"><strong>! Nutzungsdaten nicht verfügbar.</strong> Die Quelle ist gerade nicht erreichbar. Unbekannt ist nicht null. ${button('Erneut laden','retry')}</div>`:`<div class="grid cols-3"><div class="panel stat"><div class="eyebrow">Ausführungen</div><strong>${nums[0]}</strong><small>Einzelne Arbeitsschritte im Zeitraum</small></div><div class="panel stat"><div class="eyebrow">Mit Nutzungsdaten</div><strong>${nums[1]} <span style="font:13px var(--sans);color:var(--muted)">von ${nums[0]}</span></strong><small>Für diese Ausführungen liegen Messwerte vor</small></div><div class="panel stat"><div class="eyebrow">Nicht erfasst ${help('Diese Ausführungen enthalten keine verwertbare Verbrauchsmessung. Ihr Verbrauch ist unbekannt und wird nicht als null gezählt.')}</div><strong style="color:var(--amber)">${nums[2]}</strong><small>Verbrauch unbekannt · nicht null</small></div></div><div class="section-label"><h2>Was wurde verarbeitet?</h2><span class="tag">Nur erfasste Messwerte</span></div><div class="grid cols-2"><div class="panel"><div class="eyebrow">Gelesen · Eingabe</div><span class="large-number">${fmt(nums[3])}</span><p>Textbausteine aus Aufträgen, Kontext und Dateien.</p><div class="bar"><span style="width:${Math.round(nums[3]/(nums[3]+nums[4])*100)}%"></span></div></div><div class="panel"><div class="eyebrow">Erzeugt · Ausgabe</div><span class="large-number">${fmt(nums[4])}</span><p>Textbausteine aus Antworten, Änderungen und Ergebnissen.</p><div class="bar"><span style="width:${Math.round(nums[4]/(nums[3]+nums[4])*100)}%"></span></div></div></div><p class="scope">„Tokens“ sind kleine Textbausteine, keine Aufgaben oder Eurobeträge. Die Balken veranschaulichen die Größenordnung – kein Budget.</p><details><summary>Technische Aufschlüsselung nach Rolle und Worker</summary><div class="table-wrap"><table><thead><tr><th>Rolle / Worker</th><th>Ausführungen</th><th>Ohne Messung</th><th>Eingabe</th><th>Ausgabe</th><th>Cache gelesen</th><th>Cache geschrieben</th></tr></thead><tbody><tr><td>Umsetzung · Claude Code<br><span class="subtle">Modell: nicht erfasst</span></td><td>${Math.floor(nums[0]/2)}</td><td>${Math.floor(nums[2]/2)}</td><td>${fmt(Math.round(nums[3]*.6))}</td><td>${fmt(Math.round(nums[4]*.6))}</td><td>${fmt(Math.round(nums[5]*.6))}</td><td>${fmt(Math.round(nums[6]*.6))}</td></tr><tr><td>Code Reviewer · Codex<br><span class="subtle">Modell: nicht erfasst</span></td><td>${Math.ceil(nums[0]/2)}</td><td>${Math.ceil(nums[2]/2)}</td><td>${fmt(Math.round(nums[3]*.4))}</td><td>${fmt(Math.round(nums[4]*.4))}</td><td>${fmt(Math.round(nums[5]*.4))}</td><td>${fmt(Math.round(nums[6]*.4))}</td></tr></tbody></table></div><p class="subtle">Cache-Werte zeigen wiederverwendeten Kontext. Sie werden separat ausgewiesen und nicht pauschal zur Eingabe addiert.</p></details><div class="note">Die Zahlen sind Beispieldaten des Designprototyps. Fehlende Modellbeobachtung bleibt ausdrücklich „nicht erfasst“.</div>`}`;}
function chatPage(mode){if(mode)state.mode=mode;const coach=state.mode==='coach';return heading('Ein Gespräch. Ein klarer nächster Schritt.',coach?'Mit dem Product Coach denken.':'Mit Jarvis arbeiten.','Dein Gespräch bleibt im Kontext des ausgewählten Projekts.')+`<div class="tabs">${link('Jarvis','jarvis',!coach?'active':'')}${link('Product Coach','jarvis/coach',coach?'active':'')}</div><div class="chat-layout"><section class="chat-surface">${!state.messages.filter(m=>m.mode===state.mode).length?`<div class="chat-intro"><img src="assets/face.png" alt="Jarvis"><h2>${coach?'Was möchtest du möglich machen?':'Ich bin da. Was nehmen wir uns vor?'}</h2><p>${coach?'Eine Idee reicht. Gemeinsam machen wir daraus einen klaren Auftrag.':'Ich helfe dir, den Überblick zu behalten und den nächsten Schritt zu finden.'}</p><div class="suggestions">${(coach?['Eine Feature-Idee schärfen','Ein neues Projekt durchdenken']:['Was braucht mich?','Wo steht mein Projekt?','Was wurde zuletzt bearbeitet?']).map(t=>button(t,'prompt','button',`data-text="${esc(t)}"`)).join('')}</div></div>`:''}<div class="messages">${state.messages.filter(m=>m.mode===state.mode).map(m=>`<div class="message ${m.role}">${m.role==='assistant'?`<div class="eyebrow">${coach?'Product Coach':'Jarvis'} · Beispielantwort</div>`:''}${esc(m.text).replace(/\n/g,'<br>')}${m.action?`<p style="margin-top:18px">${link(m.action.text,m.action.path,'text-link')}</p>`:''}</div>`).join('')}</div>${coach&&state.chatDraft?`<div class="panel" style="margin-bottom:25px"><div class="eyebrow">Dein Auftragsentwurf</div><h3>${esc(state.chatDraft.title)}</h3><p>${esc(state.chatDraft.text)}</p>${button('Als Auftrag anlegen','coach-to-task','button primary')}</div>`:''}<form id="chat-form" class="composer"><label class="sr-only" for="chat-input">Nachricht an ${coach?'den Coach':'Jarvis'}</label><textarea id="chat-input" name="message" placeholder="${coach?'Erzähl mir von deiner Idee …':'Frag Jarvis oder beschreibe dein Ziel …'}" required></textarea><div class="composer-foot"><span>Beispielgespräch · keine KI-Verbindung</span><button class="button primary" type="submit" aria-label="Nachricht senden">${icon('send')}</button></div></form></section><aside class="chat-context"><div class="eyebrow">Unser Kontext</div><h3>${esc(project().name)}</h3><p>${esc(project().description)}</p><div class="context-item"><div class="eyebrow">${coach?'So gehen wir vor':'Nächster Schritt'}</div><p>${coach?'1. Ziel verstehen<br>2. Umfang eingrenzen<br>3. Ergebnis festlegen':state.accepted?'Nächstes Feature planen.':'Bauen aus der Akte abnehmen.'}</p>${!coach?link('Ergebnis ansehen →','abnahme/f35','text-link'):''}</div><div class="context-item"><div class="eyebrow">Du entscheidest</div><p>Ein Gespräch startet keine Arbeit. Erst ein Auftrag mit deiner Freigabe setzt die Workforce in Bewegung.</p></div><img class="rail-art" src="assets/armillary.png" alt=""></aside></div>`;}
function productPage(){return back('Projekt','projekt/'+state.project)+heading('Ergebnisse erlebbar machen','Dein Produkt öffnen.','Hier sollst du später direkt zum Produkt oder zu einer schreibgeschützten Ergebnisvorschau gelangen.')+`<div class="grid cols-2"><div class="panel"><span class="tag planned">In Entwicklung</span><h2 style="margin-top:24px">Produkt starten</h2><p>Ein klarer Einstieg in die entwickelte Anwendung. Die Startadresse kommt aus der Projektkonfiguration.</p><button class="button" disabled>Produkt öffnen</button></div><div class="panel"><span class="tag planned">In Entwicklung</span><h2 style="margin-top:24px">Ergebnisvorschau</h2><p>Ein Ergebnis ansehen, ohne es dabei zu verändern. Der Zugriff wird schreibgeschützt sein.</p><button class="button" disabled>Vorschau öffnen</button></div></div><div class="note">Diese Seite zeigt die geplante Bedienung. Im aktuellen Designprototyp wird kein lokales Produkt gestartet.</div>`;}
function settings(){return heading('Dein Atelier','Einstellungen','Eine ruhige Oberfläche, die zu deiner Arbeitsweise passt.')+`<div class="split"><section><h2>Darstellung & Bewegung</h2><label class="check"><input type="checkbox" id="motion-toggle" ${state.motion?'checked':''}><span>Sanfte Bewegung aktivieren<br><span class="subtle">Jarvis wacht auf und reagiert dezent auf den Zeiger. Die Systemeinstellung für reduzierte Bewegung hat Vorrang.</span></span></label><div class="note">Hinweise öffnen sich nach kurzem Verweilen auf einem Fragezeichen. Mit Tastaturfokus und Antippen sind sie ebenfalls erreichbar.</div><div class="section-label"><h2>Designzustände ausprobieren</h2></div><p class="subtle">Wechsle zwischen gefüllter Ansicht, leerem Zustand und fehlenden Daten.</p><label class="field">Beispielszenario<select id="scenario"><option value="normal" ${state.scenario==='normal'?'selected':''}>Normaler Projektalltag</option><option value="empty" ${state.scenario==='empty'?'selected':''}>Alles geklärt · keine offenen Entscheidungen</option><option value="unavailable" ${state.scenario==='unavailable'?'selected':''}>Eine Datenquelle ist nicht verfügbar</option></select></label><div class="action-row">${link('Entscheidungen ansehen','entscheidungen')}${link('Nutzung ansehen','nutzung')}${link('Ungültigen Ablauf ansehen','workflow/ungueltig')}</div><details><summary>Projekt & Anbindung</summary><p class="subtle">Diese Website ist eine unabhängige Designvorschau. Es gibt keine Verbindung zu deinem lokalen AI-Workforce-Server.</p><p>Spätere Anbindung: projektbezogene API unter <code>/api/projekte/&lt;id&gt;/…</code>.</p><p>Änderungen in dieser Vorschau gelten nur für die geöffnete Sitzung.</p></details><details><summary>Alle gestalteten Ansichten</summary><div class="grid cols-2">${[['Übersicht','uebersicht'],['Projektübersicht','projekte'],['Projekt anlegen','projekt/neu'],['Projekt & Roadmap','projekt/ai-workforce/roadmap'],['Projektakte','projekt/ai-workforce/akte'],['Aufträge','arbeit'],['Features','arbeit/features'],['Befunde','arbeit/befunde'],['Auftrag anlegen','auftrag/neu'],['Ablauf & Freigabe','workflow/neu'],['Rückfrage','workflow/klaerung'],['Ergebnisabnahme','abnahme/f35'],['Ausführungen','arbeit/verlauf'],['Fehlerfall','ausfuehrung/failed'],['Entscheidungen','entscheidungen'],['Fähigkeiten','faehigkeiten'],['Rollen','faehigkeiten/rollen'],['Scout','faehigkeiten/scout'],['Empfehlungen (geplant)','faehigkeiten/empfehlungen'],['Jarvis','jarvis'],['Product Coach','jarvis/coach'],['Nutzung','nutzung'],['Produktvorschau (geplant)','produkt']].map(([n,p])=>link(n+' →',p,'')).join('')}</div></details><div class="section-label"><h2>Für die Umsetzung</h2></div><p class="subtle">Gestaltung, Quellcode, Bildmotive und die Zuordnung zu den vorhandenen Endpunkten für Claude Code.</p><a class="button" href="ai-workforce-design.zip" download>Designvorlage & Quellcode herunterladen</a><div style="margin-top:25px">${button('Vorschau zurücksetzen','reset','button danger')}</div></section><aside class="summary"><h3>Silberstich & Himmelsmechanik</h3><p class="subtle">Mattes Schieferblau. Warme Elfenbeintöne. Jade als leiser Akzent. Großzügige Abstände und typografische Hierarchie.</p><img class="rail-art" src="assets/gear.png" alt=""><div class="eyebrow">Gestaltungsprinzip</div><p class="subtle">Das Wesentliche zuerst.<br>Details bei Interesse.<br>Jede Entscheidung bewusst.</p></aside></div>`;}
function notFound(){return empty('Diese Ansicht gibt es nicht.','Kehre zur Übersicht zurück.',link('Zur Übersicht','uebersicht','button primary'));}
function render(){const path=(location.hash.slice(2)||'uebersicht').split('/');shell();let html;const [p,id,tab]=path;switch(p){case'uebersicht':html=overview();break;case'projekte':html=projectsPage();break;case'projekt':if(id!=='neu'&&state.projects.some(p=>p.id===id)){activateProduct(id);shell();}html=id==='neu'?newProject():tab==='bereit'?projectReady(id):projectPage(id,tab);break;case'arbeit':html=features.some(f=>f.id===id)?featurePage(id):workPage(id||'board');break;case'auftrag':html=id==='pruefen'?taskReview():newTask();break;case'workflow':html=workflowPage(id);break;case'abnahme':html=acceptance();break;case'ausfuehrung':html=runPage(id);break;case'faehigkeiten':html=id==='scout'?scout():capabilitiesPage(id||'werkzeuge');break;case'faehigkeit':html=capabilityDetail(id);break;case'entscheidungen':html=decisions();break;case'nutzung':html=usage();break;case'jarvis':html=chatPage(id==='coach'?'coach':'jarvis');break;case'produkt':html=productPage();break;case'einstellungen':html=settings();break;default:html=notFound();}$('#main').innerHTML=html;const nav=['projekt','produkt'].includes(p)?'projekte':['auftrag','workflow','abnahme','ausfuehrung','entscheidungen'].includes(p)?'arbeit':p==='faehigkeit'?'faehigkeiten':p;$$('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===nav);if(a.dataset.nav===nav)a.setAttribute('aria-current','page')});document.title=($('#main h1')?.textContent||'Jarvis')+' · AI Workforce';document.body.classList.toggle('reduce-motion',!state.motion);document.body.classList.remove('menu-open');$('#tooltip').hidden=true;}
function go(path){if(location.hash==='#/'+path)render();else location.hash='/'+path;}
let toastTimer;function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function modal(title,body,actions=''){const d=$('#dialog');d.innerHTML=`<div class="dialog-heading"><h2>${title}</h2>${button(icon('close'),'close-modal','icon-button','aria-label="Dialog schließen"')}</div>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}`;d.showModal();}
function closeModal(){$('#dialog').close();}
function reasonModal(kind){const data={accept:['Ergebnis abnehmen','Was überzeugt dich am Ergebnis?','Abnahme bestätigen'],adjust:['Anpassung wünschen','Was soll konkret geändert werden?','Anpassung festhalten'],reject:['Ergebnis ablehnen','Warum entspricht das Ergebnis nicht deinem Auftrag?','Ablehnung bestätigen'],ack:['Fehler bestätigen','Was hast du geprüft oder entschieden?','Kenntnisnahme bestätigen'],stop:['Ausführung stoppen','Warum möchtest du die Arbeit stoppen?','Arbeit stoppen']}[kind];modal(data[0],`<form id="reason-form" data-kind="${kind}"><label class="field">${data[1]}<textarea name="reason" required minlength="5" placeholder="Eine kurze, nachvollziehbare Begründung …"></textarea></label>${kind==='adjust'?`<p class="subtle">${state.iteration<3?'Ein Anpassungsauftrag wird vorbereitet. Er startet erst nach deiner Freigabe.':'Das Limit von drei automatischen Anpassungen ist erreicht. Es wird kein weiterer Auftrag automatisch angelegt.'}</p>`:''}<div class="dialog-actions">${button('Abbrechen','close-modal')}<button class="button ${kind==='reject'||kind==='stop'?'danger':'primary'}" type="submit">${data[2]}</button></div></form>`);}
function startTask(active,reason=''){if(active&&reason.trim().length<5){toast('Bitte den Start kurz begründen.');return false;}if(active&&state.runActive){toast('Es läuft bereits eine Ausführung.');return false;}if(!state.taskDraft){toast('Beschreibe zuerst deinen Auftrag.');go('auftrag/neu');return false;}const task={...state.taskDraft,startReason:reason,id:'task-'+Date.now()+'-'+state.tasks.length,project:state.project,status:active?'active':'ready'};state.tasks.push(task);state.selectedTaskId=task.id;if(active){state.runActive=true;state.runStopped=false;state.activeTaskId=task.id;state.activeProject=task.project;state.activeWorkflowId=task.id;}state.taskDraft=null;go('workflow/'+task.id);toast(active?'Beispielausführung gestartet.':'Auftrag gespeichert. Er wartet auf deine Freigabe.');return true;}
function sendChat(text){text=text.trim();if(!text)return;const mode=state.mode;state.messages.push({role:'user',mode,text});const count=state.messages.filter(m=>m.mode===mode&&m.role==='user').length;let response,action;if(mode==='coach'){if(count===1)response='Lass uns das Ziel schärfen: Wer soll von dieser Idee profitieren – und was soll diese Person anschließend einfacher erledigen können?';else if(count===2)response='Verstanden. Was ist für die erste Version unverzichtbar? Nenne mir bitte auch ein konkretes Beispiel, an dem du ein gutes Ergebnis erkennen würdest.';else{const inputs=state.messages.filter(m=>m.mode===mode&&m.role==='user').map(m=>m.text);state.chatDraft={title:inputs[0].slice(0,100),text:'Ziel: '+inputs[0]+'\nZielgruppe & Nutzen: '+inputs[1]+'\nUmfang & Erfolgskriterium: '+inputs.slice(2).join(' ')};response='Ich habe deine Angaben zu einem ersten Auftragsentwurf zusammengefasst. Prüfe den Wortlaut und passe ihn im nächsten Schritt an. Noch wird keine Arbeit gestartet.';}}else if(/brauch|entscheid|abnahme/i.test(text)){response=state.accepted?'Das letzte Ergebnis ist abgenommen. Eine Rückfrage und ein wichtiger Befund sind im Beispiel noch offen.':'Bauen aus der Akte wartet auf deine Abnahme. Die Umsetzung und das Code Review sind abgeschlossen. Du kannst jetzt die Kriterien prüfen und entscheiden.';action={text:'Offene Entscheidungen ansehen →',path:'entscheidungen'};}else if(/zuletzt|ergebnis/i.test(text)){response='Zuletzt wurde „Bauen aus der Akte“ umgesetzt. Damit lässt sich aus einer Feature-Beschreibung ein Auftrag vorbereiten. Das Review empfiehlt die Abnahme.';action={text:'Ergebnis prüfen →',path:'abnahme/f35'};}else if(/stand|steht|projekt/i.test(text)){response='Im Beispielprojekt AI Workforce ist die Etappe „Verlässlich arbeiten“ in Umsetzung. „Bauen aus der Akte“ ist umgesetzt; die nächste geplante Erweiterung sind passende Fähigkeitsempfehlungen.';action={text:'Roadmap ansehen →',path:'projekt/'+state.project+'/roadmap'};}else{response='In dieser Designvorschau kann ich dir die Wege durch Projektstand, Entscheidungen und Aufträge zeigen. Für deine Idee kannst du mit dem Coach einen Entwurf vorbereiten.';action={text:'Mit dem Coach konkretisieren →',path:'jarvis/coach'};}state.messages.push({role:'assistant',mode,text:response,action});render();$('#chat-input')?.focus();}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;switch(a){case'menu':document.body.classList.toggle('menu-open');break;case'close-modal':closeModal();break;case'build-feature':{const f=features.find(x=>x.id===b.dataset.id);state.taskDraft={title:f.name,text:f.description,evidence:'features/'+f.id+'.md'};go('auftrag/neu');break;}case'start-task':startPermission('task');break;case'save-task':startTask(false);break;case'start-workflow':startPermission('workflow');break;case'stop-run':reasonModal('stop');break;case'decision':reasonModal(b.dataset.kind);break;case'acknowledge':reasonModal('ack');break;case'resume':state.taskDraft={title:'Browser-Prüfung fortsetzen',text:'Die Oberfläche prüfen, nachdem der notwendige Browserzugriff freigegeben wurde.',evidence:'features/f35.md'};go('auftrag/neu');break;case'answer':modal('Eine kurze Klärung',`<p class="subtle">Welche Fehlermeldung soll zuerst verständlicher werden?</p><form id="answer-form"><label class="field">Deine Antwort<textarea name="answer" required minlength="5"></textarea></label><div class="dialog-actions">${button('Abbrechen','close-modal')}<button class="button primary" type="submit">Antwort hinterlegen</button></div></form>`);break;case'repair':state.repair=true;render();toast('Beispielablauf repariert. Start weiterhin nur nach Freigabe.');break;case'validate':toast(location.hash.includes('ungueltig')&&!state.repair?'Ablauf ungültig. Reparatur erforderlich.':'Ablauf im Beispiel gültig. Die nächste Freigabe bleibt bei dir.');break;case'usage':state.usage=b.dataset.value;render();break;case'prompt':sendChat(b.dataset.text);break;case'coach-to-task':state.taskDraft={...state.chatDraft};go('auftrag/neu');break;case'retry':state.scenario='normal';render();toast('Beispieldaten wieder verfügbar.');break;case'role':modal(esc(b.dataset.role),`<div class="eyebrow">Rollenvertrag</div><p class="subtle">Die Rolle legt Verantwortung, erlaubten Umfang und Übergabekriterien fest.</p><div class="eyebrow">Vorlage & Besetzung</div><p>${esc(b.dataset.worker)}</p><div class="eyebrow">Tatsächliche Ausführung</div><p class="subtle">Die beobachtete Besetzung und Modellherkunft findest du in den Details des jeweiligen Arbeitsschritts.</p>`,link('Ausführungen ansehen','arbeit/verlauf','button primary'));break;case'shortlist':b.disabled=true;b.textContent='Auf der Merkliste';toast('Kandidat gemerkt. Nichts installiert oder freigegeben.');break;case'copy-git':navigator.clipboard?.writeText('git init\ngit add .\ngit commit -m "Projekt starten"').then(()=>toast('Befehle kopiert.')).catch(()=>toast('Bitte die Befehle aus dem Textfeld kopieren.'));break;case'reset':modal('Vorschau zurücksetzen?',`<p class="subtle">Deine Beispielaufträge, Gesprächsentwürfe und Entscheidungen dieser Sitzung werden verworfen.</p>`,button('Abbrechen','close-modal')+button('Zurücksetzen','confirm-reset','button danger'));break;case'confirm-reset':location.reload();break;}});
document.addEventListener('submit',e=>{e.preventDefault();const f=e.target,d=new FormData(f);if(f.id==='start-permission'){const reason=d.get('reason').trim();if(reason.length<5||state.runActive)return;closeModal();if(f.dataset.kind==='task')startTask(true,reason);else{const id=location.hash.split('/')[2];const t=state.tasks.find(t=>t.id===id)||(id==='neu'?state.tasks.filter(t=>t.project===state.project).at(-1):null);state.activeWorkflowId=t?.id||id;state.activeTaskId=t?.id||null;state.activeProject=state.project;if(t)t.status='active';state.runActive=true;state.runStopped=false;state.startReason=reason;render();toast('Beispielausführung mit deiner Freigabe gestartet.');}}else if(f.id==='new-project'){const name=d.get('name').trim(),id=(d.get('id')||name.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')).trim();if(!id||state.projects.some(p=>p.id===id)){toast('Bitte eine eindeutige Projekt-ID wählen.');return;}state.projects.push({id,name,folder:d.get('folder').trim(),description:d.get('description').trim()});activateProduct(id);go('projekt/'+id+'/bereit');toast('Beispielprojekt angelegt.');}else if(f.id==='new-task'){state.taskDraft={...state.taskDraft,title:d.get('title').trim(),text:d.get('text').trim(),evidence:d.get('evidence')?.trim()||''};ensureProductTaskItem();go('auftrag/pruefen');}else if(f.id==='reason-form'){const kind=f.dataset.kind,reason=d.get('reason').trim();if(reason.length<5)return;if(kind==='stop'){const t=state.tasks.find(t=>t.id===state.activeTaskId);if(t)t.status='stopped';state.runActive=false;state.runStopped=true;}else if(kind==='ack'){state.acknowledged=true;}else{state.decision={kind,reason,label:{accept:'Abgenommen',adjust:'Anpassung gewünscht',reject:'Abgelehnt'}[kind]};state.accepted=kind==='accept';if(kind==='adjust'&&state.iteration<3)state.iteration++;}closeModal();render();toast(kind==='adjust'?'Anpassungswunsch festgehalten. Kein automatischer Start.':'Entscheidung mit Begründung festgehalten.');}else if(f.id==='answer-form'){state.answer=d.get('answer').trim();state.questionAnswered=true;closeModal();render();toast('Antwort hinterlegt. Der nächste Start benötigt deine Freigabe.');}else if(f.id==='chat-form'){sendChat(d.get('message'));}else if(f.id==='scout-form'){const q=d.get('query').trim();$('#scout-results').innerHTML=`<div class="section-label"><h2>Kandidaten für „${esc(q)}“</h2><span class="tag">Beispielkatalog</span></div><div class="grid cols-2">${capabilities.filter(c=>/browser|web|prüf/i.test(q)?['browser','review'].includes(c.id):['architecture','review'].includes(c.id)).map(c=>`<div class="panel"><span class="tag">Kandidat · ${c.category}</span><h3 style="margin-top:20px">${c.name}</h3><p>${c.desc}</p>${button('Für spätere Prüfung merken','shortlist')}</div>`).join('')}</div><div class="note">Keine Live-Suche. Kandidaten müssen auf Herkunft, Berechtigungen und Eignung geprüft werden, bevor sie installiert oder eingesetzt werden.</div>`;}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='project-select'){activateProduct(el.value);go('uebersicht');}if(el.id==='work-filter'){state.filter=el.value;$('#work-results').innerHTML=workResults(location.hash.split('/')[2]);}if(el.id==='cap-filter')filterCaps();if(el.id==='scenario'){state.scenario=el.value;toast('Beispielszenario geändert.');}if(el.id==='motion-toggle'){state.motion=el.checked;document.body.classList.toggle('reduce-motion',!state.motion);}});
document.addEventListener('input',e=>{if(e.target.id==='work-search'){state.search=e.target.value;$('#work-results').innerHTML=workResults(location.hash.split('/')[2]);}if(e.target.id==='cap-search')filterCaps();});
function filterCaps(){const q=$('#cap-search').value.toLowerCase(),type=$('#cap-filter').value;$('#cap-results').innerHTML=capCards(capabilities.filter(c=>(type==='Alle Typen'||c.category===type)&&(c.name+' '+c.desc).toLowerCase().includes(q)));}
let helpTimer;function showHelp(el){const t=$('#tooltip');t.textContent=el.dataset.help;t.hidden=false;const r=el.getBoundingClientRect();t.style.left=Math.max(12,Math.min(r.left-100,innerWidth-285))+'px';t.style.top=Math.min(r.bottom+12,innerHeight-t.offsetHeight-12)+'px';el.setAttribute('aria-describedby','tooltip');}
document.addEventListener('pointerover',e=>{const el=e.target.closest('[data-help]');if(el){clearTimeout(helpTimer);helpTimer=setTimeout(()=>showHelp(el),650);}});document.addEventListener('pointerout',e=>{if(e.target.closest('[data-help]')){clearTimeout(helpTimer);$('#tooltip').hidden=true;}});document.addEventListener('focusin',e=>{if(e.target.matches('[data-help]'))showHelp(e.target);});document.addEventListener('focusout',()=>{$('#tooltip').hidden=true;});document.addEventListener('click',e=>{const h=e.target.closest('[data-help]');if(h)showHelp(h);else $('#tooltip').hidden=true;if(e.target.closest('dialog a'))closeModal();});document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#tooltip').hidden=true;document.body.classList.remove('menu-open');}});
document.addEventListener('pointermove',e=>{const face=$('.hero-face');if(!face||!state.motion||matchMedia('(prefers-reduced-motion: reduce)').matches)return;face.style.transform=`translate(${(e.clientX/innerWidth-.5)*5}px,${(e.clientY/innerHeight-.5)*3}px)`;});
function startPermission(kind){if(state.runActive){toast('Es läuft bereits eine Ausführung.');return;}modal('Umsetzung bewusst freigeben',`<p class="subtle">Claude Code wird den nächsten Schritt im Projekt <strong>${esc(project().name)}</strong> ausführen. Die Freigabe gilt nur für diesen Schritt.</p><form id="start-permission" data-kind="${kind}"><label class="field">Warum gibst du diesen Schritt frei?<textarea name="reason" required minlength="5" placeholder="Ziel und Umfang geprüft; Umsetzung kann beginnen."></textarea></label><div class="note">Designvorschau: Es startet kein echter Worker.</div><div class="dialog-actions">${button('Abbrechen','close-modal')}<button class="button primary" type="submit">Freigeben & starten</button></div></form>`);}
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#main').focus({preventScroll:true});});
render();
if(document.modelContext?.registerTool){const lifetime=new AbortController();for(const tool of [{name:'read_workforce_preview',description:'Read the current AI Workforce design preview state. All records are example data.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return{project:state.project,route:location.hash,activeRun:state.runActive,accepted:state.accepted,tasks:state.tasks.map(t=>({title:t.title,project:t.project}))};}},{name:'navigate_workforce_preview',description:'Navigate the design preview to a main screen. Does not start work.',inputSchema:{type:'object',properties:{page:{type:'string',enum:['uebersicht','projekte','arbeit','faehigkeiten','jarvis','nutzung','entscheidungen']}},required:['page'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||!['uebersicht','projekte','arbeit','faehigkeiten','jarvis','nutzung','entscheidungen'].includes(input.page))throw new Error('Unknown page');history.replaceState(null,'','#/'+input.page);render();return{page:input.page};}}]){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifetime.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});}
